begin;
create table consultorios(
 id bigint generated by default as identity primary key,clinica_id bigint not null references clinicas(id),nombre text not null check(length(trim(nombre)) between 1 and 80),
 ubicacion text not null default '' check(length(ubicacion)<=200),activo boolean not null default true,revision bigint not null default 1,creado_en timestamptz not null default clock_timestamp()
);
create unique index consultorios_nombre_unico on consultorios(clinica_id,lower(trim(nombre)));
create table consultorio_turnos(
 id bigint generated by default as identity primary key,consultorio_id bigint not null references consultorios(id),medico_id bigint not null references perfiles_medicos(id),
 desde date not null,hasta date not null,dia integer not null check(dia between 0 and 6),inicio time not null,fin time not null,activo boolean not null default true,revision bigint not null default 1,
 check(hasta>=desde and hasta-desde<=366 and fin>inicio),
 exclude using gist(consultorio_id with =,dia with =,daterange(desde,hasta,'[]') with &&,int4range(extract(epoch from inicio)::integer,extract(epoch from fin)::integer,'[)') with &&) where(activo),
 exclude using gist(medico_id with =,dia with =,daterange(desde,hasta,'[]') with &&,int4range(extract(epoch from inicio)::integer,extract(epoch from fin)::integer,'[)') with &&) where(activo)
);
alter table consultorios enable row level security;alter table consultorio_turnos enable row level security;
revoke all on consultorios,consultorio_turnos from public,anon,authenticated;
grant all on consultorios,consultorio_turnos to service_role;
grant usage,select on sequence consultorios_id_seq,consultorio_turnos_id_seq to service_role;
alter table citas add column consultorio_id bigint references consultorios(id),add column consultorio_turno_id bigint references consultorio_turnos(id),add column consultorio_registrado text;
alter table citas add constraint cita_consultorio_sin_cruces exclude using gist(consultorio_id with =,tstzrange(inicio,fin,'[)') with &&) where(consultorio_id is not null and estado in('pendiente','confirmada','atendida'));

create function public.clinica_turno_consultorio(p_medico bigint,p_inicio timestamptz,p_fin timestamptz) returns bigint language sql stable security definer set search_path=public,pg_temp as $$
 select t.id from consultorio_turnos t join consultorios c on c.id=t.consultorio_id and c.activo
 join perfiles_medicos m on m.id=t.medico_id and m.clinica_id=c.clinica_id
 where t.activo and t.medico_id=p_medico and (p_inicio at time zone 'America/Mexico_City')::date between t.desde and t.hasta
 and t.dia=extract(dow from p_inicio at time zone 'America/Mexico_City')::integer
 and (p_inicio at time zone 'America/Mexico_City')::time>=t.inicio and (p_fin at time zone 'America/Mexico_City')::time<=t.fin
 and (p_inicio at time zone 'America/Mexico_City')::date=(p_fin at time zone 'America/Mexico_City')::date order by t.id limit 1
$$;
create function public.clinica_consultorio_disponible(p_medico bigint,p_inicio timestamptz,p_fin timestamptz,p_excluir bigint default null) returns boolean language sql stable security definer set search_path=public,pg_temp as $$
 select not exists(select 1 from consultorio_turnos where medico_id=p_medico and activo)
 or exists(select 1 from consultorio_turnos t where t.id=clinica_turno_consultorio(p_medico,p_inicio,p_fin)
 and not exists(select 1 from citas c where c.id is distinct from p_excluir and c.consultorio_id=t.consultorio_id and c.estado in('pendiente','confirmada','atendida') and tstzrange(c.inicio,c.fin,'[)')&&tstzrange(p_inicio,p_fin,'[)')))
$$;
create function public.clinica_cita_consultorio() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
declare t consultorio_turnos;c consultorios;
begin
 perform pg_advisory_xact_lock(37201,0);
 if new.estado not in('pendiente','confirmada','atendida') then return new;end if;
 if tg_op='UPDATE' and (new.inicio,new.fin,new.medico_id,new.consultorio_id,new.consultorio_turno_id) is not distinct from (old.inicio,old.fin,old.medico_id,old.consultorio_id,old.consultorio_turno_id) then return new;end if;
 if not clinica_consultorio_disponible(new.medico_id,new.inicio,new.fin,new.id) then raise exception 'No hay consultorio disponible para ese médico en el horario seleccionado' using errcode='23P01';end if;
 select * into t from consultorio_turnos where id=clinica_turno_consultorio(new.medico_id,new.inicio,new.fin);
 select * into c from consultorios where id=t.consultorio_id;
 new.consultorio_id:=c.id;new.consultorio_turno_id:=t.id;new.consultorio_registrado:=case when c.id is not null then concat_ws(' · ',c.nombre,nullif(c.ubicacion,'')) end;
 return new;
end $$;
create trigger cita_consultorio before insert or update on citas for each row execute function clinica_cita_consultorio();

alter function public.clinica_turnos_reserva(bigint,bigint,date) rename to clinica_turnos_reserva_v34;
revoke all on function clinica_turnos_reserva_v34(bigint,bigint,date) from public,anon,authenticated,service_role;
create function public.clinica_turnos_reserva(p_paciente bigint,p_medico bigint,p_desde date default null) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare r jsonb;
begin
 r:=clinica_turnos_reserva_v34(p_paciente,p_medico,p_desde);
 return r||jsonb_build_object('turnos',coalesce((select jsonb_agg(x order by x->>'inicio') from jsonb_array_elements(r->'turnos') x where clinica_consultorio_disponible(p_medico,(x->>'inicio')::timestamptz,(x->>'fin')::timestamptz)),'[]'::jsonb));
end $$;
alter function public.clinica_turnos_cita_actor(bigint,bigint,text,date) rename to clinica_turnos_cita_actor_v34;
revoke all on function clinica_turnos_cita_actor_v34(bigint,bigint,text,date) from public,anon,authenticated,service_role;
create function public.clinica_turnos_cita_actor(p_usuario bigint,p_cita bigint,p_version text,p_desde date default null) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare r jsonb;m bigint;
begin
 r:=clinica_turnos_cita_actor_v34(p_usuario,p_cita,p_version,p_desde);select medico_id into m from citas where id=p_cita;
 return r||jsonb_build_object('turnos',coalesce((select jsonb_agg(x order by x->>'inicio') from jsonb_array_elements(r->'turnos') x where clinica_consultorio_disponible(m,(x->>'inicio')::timestamptz,(x->>'fin')::timestamptz,p_cita)),'[]'::jsonb));
end $$;
create function public.clinica_filtrar_consultorios(p_medico bigint,p_turnos jsonb) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
begin
 perform clinica_requerir_sesion();if jsonb_typeof(p_turnos) is distinct from 'array' or jsonb_array_length(p_turnos)>1000 then raise exception 'Horarios inválidos';end if;
 return coalesce((select jsonb_agg(x) from jsonb_array_elements(p_turnos) x where clinica_consultorio_disponible(p_medico,(x->>'inicio')::timestamptz,(x->>'fin')::timestamptz,(x->>'excluir')::bigint)),'[]'::jsonb);
end $$;

create function public.clinica_consultorios_panel() returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
begin
 perform clinica_requerir_sesion();if clinica_rol() is null or clinica_rol() not in('admin','recepcionista') then raise exception 'Sin acceso a consultorios' using errcode='42501';end if;
 return jsonb_build_object('clinicas',coalesce((select jsonb_agg(jsonb_build_object('id',id,'nombre',nombre)) from clinicas where esta_activo),'[]'::jsonb),
 'medicos',coalesce((select jsonb_agg(jsonb_build_object('id',m.id,'nombre',u.nombre_completo,'clinicaId',m.clinica_id,'asignado',exists(select 1 from consultorio_turnos where medico_id=m.id and activo and hasta>=(clock_timestamp() at time zone 'America/Mexico_City')::date))) from perfiles_medicos m join usuarios u on u.id=m.usuario_id and u.esta_activo where m.esta_activo),'[]'::jsonb),
 'salas',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'clinicaId',c.clinica_id,'nombre',c.nombre,'ubicacion',c.ubicacion,'activo',c.activo,'version',md5(to_jsonb(c)::text)) order by c.nombre) from consultorios c),'[]'::jsonb),
 'turnos',coalesce((select jsonb_agg(jsonb_build_object('id',t.id,'consultorioId',t.consultorio_id,'medicoId',t.medico_id,'medico',u.nombre_completo,'desde',t.desde,'hasta',t.hasta,'dia',t.dia,'inicio',t.inicio,'fin',t.fin,'activo',t.activo,'version',md5(to_jsonb(t)::text)) order by t.desde desc,t.dia,t.inicio) from consultorio_turnos t join perfiles_medicos m on m.id=t.medico_id join usuarios u on u.id=m.usuario_id where t.hasta>=(clock_timestamp() at time zone 'America/Mexico_City')::date-30),'[]'::jsonb));
end $$;
create function public.clinica_consultorios_mutar(p_accion text,p_datos jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare c consultorios;t consultorio_turnos;m perfiles_medicos;n bigint;
begin
 if clinica_rol() is distinct from 'admin' then raise exception 'Solo administración gestiona consultorios' using errcode='42501';end if;
 if p_accion in('sala','editar_sala') then
  if length(trim(coalesce(p_datos->>'nombre',''))) not between 1 and 80 or length(coalesce(p_datos->>'ubicacion',''))>200 then raise exception 'Revisa nombre y ubicación';end if;
  if p_accion='sala' then
   if not exists(select 1 from clinicas where id=(p_datos->>'clinicaId')::bigint and esta_activo) then raise exception 'Selecciona una clínica activa';end if;
   insert into consultorios(clinica_id,nombre,ubicacion) values((p_datos->>'clinicaId')::bigint,trim(p_datos->>'nombre'),trim(coalesce(p_datos->>'ubicacion',''))) returning id into n;
  else
   select * into c from consultorios where id=(p_datos->>'id')::bigint for update;
   if c.id is null or md5(to_jsonb(c)::text) is distinct from p_datos->>'version' then raise exception 'El consultorio cambió. Actualiza la pantalla' using errcode='40001';end if;
   if exists(select 1 from citas where consultorio_id=c.id and estado in('pendiente','confirmada') and fin>clock_timestamp()) then raise exception 'El consultorio tiene citas vigentes. Coordina sus cambios antes de modificarlo';end if;
   if jsonb_typeof(p_datos->'activo') is distinct from 'boolean' then raise exception 'Indica el estado del consultorio';end if;
   if not (p_datos->>'activo')::boolean and exists(select 1 from consultorio_turnos where consultorio_id=c.id and activo and hasta>=(clock_timestamp() at time zone 'America/Mexico_City')::date) then raise exception 'Desactiva primero sus turnos';end if;
   update consultorios set nombre=trim(p_datos->>'nombre'),ubicacion=trim(coalesce(p_datos->>'ubicacion','')),activo=(p_datos->>'activo')::boolean,revision=revision+1 where id=c.id;n:=c.id;
  end if;
 elsif p_accion='turno' then
  select * into c from consultorios where id=(p_datos->>'consultorioId')::bigint and activo;
  select pm.* into m from perfiles_medicos pm join usuarios u on u.id=pm.usuario_id and u.esta_activo where pm.id=(p_datos->>'medicoId')::bigint and pm.esta_activo;
  if c.id is null or m.id is null or m.clinica_id<>c.clinica_id then raise exception 'El médico y consultorio deben estar activos en la misma clínica';end if;
  if (p_datos->>'desde')::date<(clock_timestamp() at time zone 'America/Mexico_City')::date or (p_datos->>'hasta')::date>(clock_timestamp() at time zone 'America/Mexico_City')::date+366 then raise exception 'Selecciona fechas desde hoy y dentro del próximo año';end if;
  insert into consultorio_turnos(consultorio_id,medico_id,desde,hasta,dia,inicio,fin) values(c.id,m.id,(p_datos->>'desde')::date,(p_datos->>'hasta')::date,(p_datos->>'dia')::integer,(p_datos->>'inicio')::time,(p_datos->>'fin')::time) returning * into t;n:=t.id;
  update citas set consultorio_id=c.id,consultorio_turno_id=t.id where medico_id=m.id and estado in('pendiente','confirmada') and inicio>clock_timestamp() and consultorio_id is null and clinica_turno_consultorio(m.id,inicio,fin)=t.id;
 elsif p_accion='baja_turno' then
  select * into t from consultorio_turnos where id=(p_datos->>'id')::bigint for update;
  if t.id is null or md5(to_jsonb(t)::text) is distinct from p_datos->>'version' then raise exception 'El turno cambió. Actualiza la pantalla' using errcode='40001';end if;
  if exists(select 1 from citas where consultorio_turno_id=t.id and estado in('pendiente','confirmada') and fin>clock_timestamp()) then raise exception 'El turno tiene citas vigentes. Coordina su reasignación antes de desactivarlo';end if;
  update consultorio_turnos set activo=false,revision=revision+1 where id=t.id;n:=t.id;
 else raise exception 'Acción de consultorios inválida';end if;
 return jsonb_build_object('ok',true,'id',n,'mensaje','Consultorio y asignaciones actualizados.');
end $$;
create trigger consultorios_auditar after insert or update on consultorios for each row execute function clinica_auditar();
create trigger consultorio_turnos_auditar after insert or update on consultorio_turnos for each row execute function clinica_auditar();
revoke all on function clinica_turno_consultorio(bigint,timestamptz,timestamptz),clinica_consultorio_disponible(bigint,timestamptz,timestamptz,bigint),clinica_cita_consultorio(),clinica_turnos_reserva(bigint,bigint,date),clinica_turnos_cita_actor(bigint,bigint,text,date),clinica_consultorios_mutar(text,jsonb) from public,anon,authenticated,service_role;
revoke all on function clinica_consultorios_panel(),clinica_filtrar_consultorios(bigint,jsonb) from public,anon;
grant execute on function clinica_consultorios_panel(),clinica_filtrar_consultorios(bigint,jsonb) to authenticated;
create or replace function public.clinica_version() returns integer language sql stable as $$select 35$$;
notify pgrst,'reload schema';commit;
